    for (int i = 0; i + totalLen <= textLen; i++) {
        // Check if text[i..i+totalLen-1] is a concatenation of all elems
        string sub = text.substr(i, totalLen);
        // Try all permutations? Too slow for large n
        // Use recursive matching
        multiset<string> remaining(elems.begin(), elems.end());

        function<bool(int, multiset<string>&)> check = [&](int pos, multiset<string>& rem) -> bool {
            if (rem.empty()) return pos == totalLen;
            for (auto it = rem.begin(); it != rem.end(); ) {
                string s = *it;
                if (pos + (int)s.size() <= totalLen && sub.substr(pos, s.size()) == s) {
                    auto nit = rem.erase(it);
                    if (check(pos + s.size(), rem)) {
                        rem.insert(s);
                        return true;
                    }
                    rem.insert(s);
                    it = nit;
                } else {
                    ++it;
                }
            }
            return false;
        };

        if (check(0, remaining)) count++;
    }

    cout << count << endl;
    return 0;
}

