/*
We are given n element strings and a text.
We need to count occurrences of every possible concatenation formed by all n strings
in any order, counting distinct occurrences in the text.

Interpretation used:
- For each permutation p of the n strings, form S = a[p1] + a[p2] + ... + a[pn].
- If multiple permutations produce the same final string, count that string only once.
- Answer = sum over all distinct such strings of number of occurrences in text
  (overlaps allowed).

Constraints are not shown, so we implement a robust solution:
1) Generate all distinct concatenations via DFS over multiset of strings.
   To avoid duplicate work from identical element strings, compress equal strings.
2) Insert all distinct concatenations into an Aho-Corasick automaton.
3) Scan the text and sum terminal counts.

This is suitable when n is small enough that the number of distinct concatenations
is manageable, which is the natural setting for this kind of problem.
*/

struct AhoCorasick {
    struct Node {
        unordered_map<char,int> next;
        int link = 0;
        long long out = 0; // number of patterns ending here
    };
    vector<Node> t;
    AhoCorasick() { t.push_back(Node()); }

    void add(const string& s) {
        int v = 0;
        for (char c : s) {
            auto it = t[v].next.find(c);
            if (it == t[v].next.end()) {
                t[v].next[c] = (int)t.size();
                t.push_back(Node());
                v = (int)t.size() - 1;
            } else v = it->second;
        }
        t[v].out += 1;
    }

    void build() {
        queue<int> q;
        for (auto &e : t[0].next) {
            q.push(e.second);
            t[e.second].link = 0;
        }
        while (!q.empty()) {
            int v = q.front(); q.pop();
            int link = t[v].link;
            t[v].out += t[link].out;

            for (auto &e : t[v].next) {
                char c = e.first;
                int u = e.second;
                int j = t[v].link;
                while (j && !t[j].next.count(c)) j = t[j].link;
                if (t[j].next.count(c)) t[u].link = t[j].next[c];
                else t[u].link = 0;
                q.push(u);
            }
        }
    }

    long long countInText(const string& text) {
        long long ans = 0;
        int v = 0;
        for (char c : text) {
            while (v && !t[v].next.count(c)) v = t[v].link;
            if (t[v].next.count(c)) v = t[v].next[c];
            else v = 0;
            ans += t[v].out;
        }
        return ans;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    vector<string> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    string text;
    cin >> text;

    sort(a.begin(), a.end());

    // Compress equal strings.
    vector<string> vals;
    vector<int> cnt;
    for (int i = 0; i < n; ) {
        int j = i;
        while (j < n && a[j] == a[i]) ++j;
        vals.push_back(a[i]);
        cnt.push_back(j - i);
        i = j;
    }

    AhoCorasick ac;
    string cur;

    function<void()> dfs = [&]() {
        bool done = true;
        for (int c : cnt) if (c) { done = false; break; }
        if (done) {
            ac.add(cur);
            return;
        }
        for (int i = 0; i < (int)vals.size(); ++i) {
            if (!cnt[i]) continue;
            cnt[i]--;
            cur += vals[i];
            dfs();
            cur.resize(cur.size() - vals[i].size());
            cnt[i]++;
        }
    };

    dfs();
    ac.build();
    cout << ac.countInText(text) << '\n';
    return 0;
}

