int n;
int totalLen;

int check(const char *s, int remaining) {
    if (remaining == 0) return 1;
    for (int i = 0; i < n; i++) {
        if (!used[i]) {
            int wlen = strlen(words[i]);
            if (strncmp(s, words[i], wlen) == 0) {
                used[i] = 1;
                if (check(s + wlen, remaining - 1)) {
                    used[i] = 0;
                    return 1;
                }
                used[i] = 0;
            }
        }
    }
    return 0;
}

