typedef long long ll;

typedef struct {
    char *s;
    int len;
} Str;

static int cmp_str(const void *a, const void *b) {
    const Str *x = (const Str *)a;
    const Str *y = (const Str *)b;
    int c = strcmp(x->s, y->s);
    if (c != 0) return c;
    return x->len - y->len;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Str *arr = (Str *)malloc(sizeof(Str) * n);
    if (!arr) return 0;

    char buf[10005];
    for (int i = 0; i < n; i++) {
        if (scanf("%10000s", buf) != 1) return 0;
        int len = (int)strlen(buf);
        arr[i].s = (char *)malloc(len + 1);
        if (!arr[i].s) return 0;
        strcpy(arr[i].s, buf);
        arr[i].len = len;
    }

    if (scanf("%10000s", buf) != 1) return 0;
    char *text = (char *)malloc(strlen(buf) + 1);
    if (!text) return 0;
    strcpy(text, buf);
    int m = (int)strlen(text);

    qsort(arr, n, sizeof(Str), cmp_str);

    /* Compress identical strings and count multiplicities */
    char **uniq = (char **)malloc(sizeof(char *) * n);
    int *ulen = (int *)malloc(sizeof(int) * n);
    ll *cnt = (ll *)malloc(sizeof(ll) * n);
    if (!uniq || !ulen || !cnt) return 0;

    int k = 0;
    for (int i = 0; i < n; ) {
        int j = i + 1;
        while (j < n && strcmp(arr[i].s, arr[j].s) == 0) j++;
        uniq[k] = arr[i].s;
        ulen[k] = arr[i].len;
        cnt[k] = j - i;
        for (int t = i + 1; t < j; t++) free(arr[t].s);
        k++;
        i = j;
    }
    free(arr);

    ll ans = 0;

    /* Count all ordered pairs (a,b), including a==b with multiplicity */
    for (int a = 0; a < k; a++) {
        for (int b = 0; b < k; b++) {
            int L1 = ulen[a], L2 = ulen[b];
            int L = L1 + L2;
            if (L > m) continue;

            char *pat = (char *)malloc(L + 1);
            if (!pat) return 0;
            memcpy(pat, uniq[a], L1);
            memcpy(pat + L1, uniq[b], L2);
            pat[L] = '\0';

            ll occ = 0;
            for (int i = 0; i + L <= m; i++) {
                if (memcmp(text + i, pat, L) == 0) occ++;
            }

            if (a == b) {
                ans += occ * cnt[a] * cnt[a];
            } else {
                ans += occ * cnt[a] * cnt[b];
            }

            free(pat);
        }
    }

    printf("%lld\n", ans);

    for (int i = 0; i < k; i++) free(uniq[i]);
    free(uniq);
    free(ulen);
    free(cnt);
    free(text);

    return 0;
}

