                    count++;
                    break; // count position once
                }
            }
        }
        System.out.println(count);
    }

    static void generatePermutations(boolean[] used, String current, int n) {
        if (current.length() > 0 && !patterns.contains(current)) {
            // Check if this is a complete permutation
        }
        // Only complete permutations
        boolean allUsed = true;
        for (boolean u : used) if (!u) { allUsed = false; break; }
        if (allUsed) {
            patterns.add(current);
