public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        List<String> elements = new ArrayList<>();

        // Read element strings until an empty line
        while ((line = br.readLine()) != null && !line.isEmpty()) {
            elements.add(line.trim());
        }

        // Read the text
        StringBuilder textBuilder = new StringBuilder();
        while ((line = br.readLine()) != null) {
            textBuilder.append(line);
        }
        String text = textBuilder.toString();

        int n = elements.size();
        Set<String> concatenated = new HashSet<>();

        // Generate all permutations of concatenations
        boolean[] used = new boolean[n];
        generatePermutations(elements, used, new StringBuilder(), concatenated);

        // Count occurrences in text (including overlaps)
        int totalCount = 0;
        for (String pattern : concatenated) {
            totalCount += countOccurrences(text, pattern);
        }

        System.out.println(totalCount);
    }

    private static void generatePermutations(List<String> elements, boolean[] used, 
                                             StringBuilder current, Set<String> result) {
        boolean allUsed = true;
        for (boolean u : used) {
            if (!u) {
                allUsed = false;
                break;
            }
        }

        if (allUsed) {
            // Only add if at least one element was used (non-empty)
            if (current.length() > 0) {
                result.add(current.toString());
            }
            return;
        }

        for (int i = 0; i < elements.size(); i++) {
            if (!used[i]) {
                used[i] = true;
                int startLen = current.length();
                current.append(elements.get(i));
                generatePermutations(elements, used, current, result);
                current.setLength(startLen);
                used[i] = false;
            }
        }
    }

    private static int countOccurrences(String text, String pattern) {
        if (pattern.isEmpty()) return 0;
        int count = 0;
        int idx = 0;
        while ((idx = text.indexOf(pattern, idx)) != -1) {
            count++;
            idx++; // Allow overlapping
        }
        return count;
    }
}

