import java.util.*;

/*
 Since the statement available here is incomplete/ambiguous, this solution targets the
 natural interpretation:

 Given:
 - n element strings
 - a text T

 Count, over all ordered pairs of element strings (si, sj), how many occurrences of
 the concatenated string si + sj appear in T.

 Distinct occurrences are counted by position, overlaps are allowed, and identical
 strings are handled by counting all ordered pairs (including i == j if both positions
 exist in the input list).

 Approach:
 - Build an Aho-Corasick automaton for all unique element strings.
 - Scan the text once.
 - For every position p in the text, record how many input strings end at p
   (grouped by unique string id with multiplicity).
 - From these matches, build:
     startCount[id][pos] = multiplicity of string id starting at pos
     endCount[id][pos]   = multiplicity of string id ending at pos
 - For every boundary b between characters, the number of occurrences of si+sj crossing
   that boundary is:
       endCount[i][b] * startCount[j][b+1]
   Summing over all ordered pairs gives:
       (sum over i endCount[i][b]) * (sum over j startCount[j][b+1])
   which already correctly includes multiplicities and identical strings.
 - Therefore we only need total number of matched input strings ending/starting at each
   position, not per-id details.

 Complexity:
 - O(total length of element strings + |T| + number of matches)

 Input format assumed:
 n
 s1
 s2
 ...
 sn
 text

 Output:
 single integer answer

 If the original judge uses a different format, adjust parsing accordingly.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }

    static class Node {
        int[] next = new int[26];
        int link = 0;
        ArrayList<Integer> out = new ArrayList<>();
        Node() {
            Arrays.fill(next, -1);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        String first = fs.next();
        if (first == null) return;
        int n = Integer.parseInt(first);

        String[] arr = new String[n];
        HashMap<String, Integer> idMap = new HashMap<>();
        ArrayList<String> uniq = new ArrayList<>();
        ArrayList<Integer> multList = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            arr[i] = fs.next();
            Integer id = idMap.get(arr[i]);
            if (id == null) {
                id = uniq.size();
                idMap.put(arr[i], id);
                uniq.add(arr[i]);
                multList.add(1);
            } else {
                multList.set(id, multList.get(id) + 1);
            }
        }

        String text = fs.next();
        if (text == null) text = "";

        int m = uniq.size();
        int[] multiplicity = new int[m];
        int[] lengths = new int[m];
        for (int i = 0; i < m; i++) {
            multiplicity[i] = multList.get(i);
            lengths[i] = uniq.get(i).length();
        }

        ArrayList<Node> trie = new ArrayList<>();
        trie.add(new Node());

        for (int id = 0; id < m; id++) {
            String s = uniq.get(id);
            int v = 0;
            for (int i = 0; i < s.length(); i++) {
                int c = s.charAt(i) - 'a';
                if (c < 0 || c >= 26) {
                    throw new RuntimeException("This solution assumes lowercase latin letters only.");
                }
                if (trie.get(v).next[c] == -1) {
                    trie.get(v).next[c] = trie.size();
                    trie.add(new Node());
                }
                v = trie.get(v).next[c];
            }
            trie.get(v).out.add(id);
        }

        Queue<Integer> q = new ArrayDeque<>();
        for (int c = 0; c < 26; c++) {
            int u = trie.get(0).next[c];
            if (u != -1) {
                trie.get(u).link = 0;
                q.add(u);
            } else {
                trie.get(0).next[c] = 0;
            }
        }

        while (!q.isEmpty()) {
            int v = q.poll();
            int link = trie.get(v).link;
            trie.get(v).out.addAll(trie.get(link).out);
            for (int c = 0; c < 26; c++) {
                int u = trie.get(v).next[c];
                if (u != -1) {
                    trie.get(u).link = trie.get(link).next[c];
                    q.add(u);
                } else {
                    trie.get(v).next[c] = trie.get(link).next[c];
                }
            }
        }

        int L = text.length();
        long[] endTotal = new long[L];
        long[] startTotal = new long[L];

        int state = 0;
        for (int i = 0; i < L; i++) {
            int c = text.charAt(i) - 'a';
            if (c < 0 || c >= 26) {
                throw new RuntimeException("This solution assumes lowercase latin letters only.");
            }
            state = trie.get(state).next[c];
            for (int id : trie.get(state).out) {
                int lenStr = lengths[id];
                int start = i - lenStr + 1;
                if (start >= 0) {
                    long add = multiplicity[id];
                    endTotal[i] += add;
                    startTotal[start] += add;
                }
            }
        }

        long ans = 0;
        for (int b = 0; b + 1 < L; b++) {
            ans += endTotal[b] * startTotal[b + 1];
        }

        System.out.println(ans);
    }
}
